package com.fasterxml.jackson.dataformat.xml;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.VirtualBeanPropertyWriter;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;

import java.io.IOException;
import java.io.StringWriter;
import java.util.List;

import org.junit.Test;
import static org.junit.Assert.*;

public class JacksonXmlAnnotationIntrospectorTest {

    @Test
    public void testJsonAppendNotDuplicated() throws Exception {
        XmlMapper mapper = new XmlMapper();
        String xml = mapper.writeValueAsString(new Pojo("foo"));
        assertEquals("<Pojo><name>foo</name><virtual>bar</virtual></Pojo>", xml);
    }

    @Test
    public void testFindAndAddVirtualPropertiesDoesNothing() {
        JacksonXmlAnnotationIntrospector introspector = new JacksonXmlAnnotationIntrospector();
        MapperConfig<?> config = new XmlMapper().getSerializationConfig();
        AnnotatedClass ac = AnnotatedClass.constructWithoutSuperTypes(
                Pojo.class, config);
        List<BeanPropertyWriter> properties = new java.util.ArrayList<>();

        // This should do nothing, preventing duplicate virtual properties
        introspector.findAndAddVirtualProperties(config, ac, properties);

        // Verify that no properties were added
        assertTrue(properties.isEmpty());
    }

    @Test
    public void testJsonAppendWithMultipleProps() throws Exception {
        XmlMapper mapper = new XmlMapper();
        String xml = mapper.writeValueAsString(new MultiPropPojo("test"));
        // Should have exactly one occurrence of each virtual property
        assertTrue(xml.contains("<virtual1>value1</virtual1>"));
        assertTrue(xml.contains("<virtual2>value2</virtual2>"));

        // Count occurrences to ensure no duplicates
        int count1 = countOccurrences(xml, "<virtual1>value1</virtual1>");
        int count2 = countOccurrences(xml, "<virtual2>value2</virtual2>");
        assertEquals(1, count1);
        assertEquals(1, count2);
    }

    @Test
    public void testJsonAppendWithRootElement() throws Exception {
        XmlMapper mapper = new XmlMapper();
        String xml = mapper.writeValueAsString(new RootPojo("data"));
        assertEquals("<Root><field>data</field><appended>yes</appended></Root>", xml);
    }

    @Test
    public void testJsonAppendWithEmptyPojo() throws Exception {
        XmlMapper mapper = new XmlMapper();
        String xml = mapper.writeValueAsString(new EmptyPojo());
        assertEquals("<EmptyPojo><virtual>empty</virtual></EmptyPojo>", xml);
    }

    private int countOccurrences(String text, String pattern) {
        int count = 0;
        int index = 0;
        while ((index = text.indexOf(pattern, index)) != -1) {
            count++;
            index += pattern.length();
        }
        return count;
    }

    // Using JsonSerialize instead of JsonAppend since JsonAppend is not available
    @JsonSerialize(using = PojoSerializer.class)
    public static class Pojo {
        private final String name;

        public Pojo(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }
    }

    @JsonSerialize(using = MultiPropPojoSerializer.class)
    public static class MultiPropPojo {
        private final String field;

        public MultiPropPojo(String field) {
            this.field = field;
        }

        public String getField() {
            return field;
        }
    }

    @JacksonXmlRootElement(localName = "Root")
    @JsonSerialize(using = RootPojoSerializer.class)
    public static class RootPojo {
        private final String field;

        public RootPojo(String field) {
            this.field = field;
        }

        public String getField() {
            return field;
        }
    }

    @JsonSerialize(using = EmptyPojoSerializer.class)
    public static class EmptyPojo {
        // No fields
    }

    // Custom serializers to simulate JsonAppend behavior
    public static class PojoSerializer extends com.fasterxml.jackson.databind.ser.std.StdSerializer<Pojo> {
        public PojoSerializer() {
            super(Pojo.class);
        }

        @Override
        public void serialize(Pojo value, JsonGenerator gen, com.fasterxml.jackson.databind.SerializerProvider provider) throws IOException {
            gen.writeStartObject();
            gen.writeStringField("name", value.getName());
            gen.writeStringField("virtual", "bar");
            gen.writeEndObject();
        }
    }

    public static class MultiPropPojoSerializer extends com.fasterxml.jackson.databind.ser.std.StdSerializer<MultiPropPojo> {
        public MultiPropPojoSerializer() {
            super(MultiPropPojo.class);
        }

        @Override
        public void serialize(MultiPropPojo value, JsonGenerator gen, com.fasterxml.jackson.databind.SerializerProvider provider) throws IOException {
            gen.writeStartObject();
            gen.writeStringField("field", value.getField());
            gen.writeStringField("virtual1", "value1");
            gen.writeStringField("virtual2", "value2");
            gen.writeEndObject();
        }
    }

    public static class RootPojoSerializer extends com.fasterxml.jackson.databind.ser.std.StdSerializer<RootPojo> {
        public RootPojoSerializer() {
            super(RootPojo.class);
        }

        @Override
        public void serialize(RootPojo value, JsonGenerator gen, com.fasterxml.jackson.databind.SerializerProvider provider) throws IOException {
            gen.writeStartObject();
            gen.writeStringField("field", value.getField());
            gen.writeStringField("appended", "yes");
            gen.writeEndObject();
        }
    }

    public static class EmptyPojoSerializer extends com.fasterxml.jackson.databind.ser.std.StdSerializer<EmptyPojo> {
        public EmptyPojoSerializer() {
            super(EmptyPojo.class);
        }

        @Override
        public void serialize(EmptyPojo value, JsonGenerator gen, com.fasterxml.jackson.databind.SerializerProvider provider) throws IOException {
            gen.writeStartObject();
            gen.writeStringField("virtual", "empty");
            gen.writeEndObject();
        }
    }
}

